using namespace std;

class Solution {
    int memo[1005][1005];
    int n;

    int dp(int last, int i, const vector<int>& nums) {
        if (i >= n) return nums[last];
        if (i == n - 1) return max(nums[last], nums[i]);
        if (memo[last][i] != -1) return memo[last][i];

        int c1 = max(nums[i], nums[i + 1]) + dp(last, i + 2, nums);
        int c2 = max(nums[last], nums[i]) + dp(i + 1, i + 2, nums);
        int c3 = max(nums[last], nums[i + 1]) + dp(i, i + 2, nums);

        return memo[last][i] = min({c1, c2, c3});
    }

public:
    int minCost(vector<int>& nums) {
        n = nums.size();
        memset(memo, -1, sizeof(memo));
        return dp(0, 1, nums);
    }
};

import java.util.Arrays;

class Solution {
    private int[][] memo;
    private int n;

    private int dp(int last, int i, int[] nums) {
        if (i >= n) return nums[last];
        if (i == n - 1) return Math.max(nums[last], nums[i]);
        if (memo[last][i] != -1) return memo[last][i];

        int c1 = Math.max(nums[i], nums[i + 1]) + dp(last, i + 2, nums);
        int c2 = Math.max(nums[last], nums[i]) + dp(i + 1, i + 2, nums);
        int c3 = Math.max(nums[last], nums[i + 1]) + dp(i, i + 2, nums);

        return memo[last][i] = Math.min(c1, Math.min(c2, c3));
    }

    public int minCost(int[] nums) {
        n = nums.length;
        memo = new int[n + 2][n + 2];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dp(0, 1, nums);
    }
}

