var minCost = function(nums) {
    const n = nums.length;
    const memo = new Map();

    function dp(last, i) {
        if (i >= n) return nums[last];
        if (i === n - 1) return Math.max(nums[last], nums[i]);
        const key = `${last},${i}`;
        if (memo.has(key)) return memo.get(key);

        const c1 = Math.max(nums[i], nums[i + 1]) + dp(last, i + 2);
        const c2 = Math.max(nums[last], nums[i]) + dp(i + 1, i + 2);
        const c3 = Math.max(nums[last], nums[i + 1]) + dp(i, i + 2);

        const res = Math.min(c1, c2, c3);
        memo.set(key, res);
        return res;
    }

    return dp(0, 1);
};
